-- REVIEW ONLY: no production deployment. Generated by scripts/build-arena-runes-staged.mjs.
-- Requires rune ledger, battle snapshots, effects, damage bridge and the exact
-- checked-in Arena functions. A drifted function aborts the entire transaction.
BEGIN;
-- Backward compatible: rooms already active at cutover use their original
-- damage, dodge and crit because they have no pinned rune fighter rows.
-- Lock both replacements atomically; existing battles keep their current state.
LOCK TABLE public.arena_rooms IN ACCESS EXCLUSIVE MODE;
DO $guard$
DECLARE start_body text; resolve_body text;
BEGIN
 -- Existing active rooms are handled by the no-snapshot compatibility path.
 SELECT p.prosrc INTO start_body FROM pg_catalog.pg_proc p WHERE p.oid=pg_catalog.to_regprocedure('public.arena_start_room(uuid)');
 SELECT p.prosrc INTO resolve_body FROM pg_catalog.pg_proc p WHERE p.oid=pg_catalog.to_regprocedure('public.arena_resolve_round(uuid)');
 IF start_body IS DISTINCT FROM $expected_start$
DECLARE
v_room arena_rooms%ROWTYPE;
v_humans int;
v_present int;
v_total int;
v_avg_lvl numeric;
v_avg_rating numeric;
v_avg_attack numeric;
v_avg_defense numeric;
v_avg_hp numeric;
v_avg_crit numeric;
v_lvl int;
v_hp int;
v_name text;
v_names text[] := ARRAY['Рагнар','Сигурд','Хельга','Бьорн','Ивар','Астрид','Торвальд','Фрейя','Улаф','Лагерта',
'Хротгар','Эйрик','Сольвейг','Гуннар','Кнуд','Ингрид','Харальд','Тюр','Вали','Сван','ВолкСевера','Берсерк',
'ТёмныйЯрл','Ледоруб','Медведь','Skald','Valkyr','Drakkar','Fenrir','NordKing','Wolfhart','Grimnir','Тордис',
'Хаук','Агнар','Ярослав','Мстислав','Дружинник','СтальнойКулак','Варяг'];
v_c1 int;
v_c2 int;
i int;
BEGIN
SELECT * INTO v_room FROM arena_rooms WHERE id = p_room;
-- Scale newly generated combat opponents to real participating heroes.
SELECT count(*), COALESCE(avg(level), 1), COALESCE(avg(rating), 1000),
       COALESCE(avg(attack), 20), COALESCE(avg(defense), 5),
       COALESCE(avg(max_hp), 100), COALESCE(avg(crit_chance), 5)
INTO v_humans, v_avg_lvl, v_avg_rating,
     v_avg_attack, v_avg_defense, v_avg_hp, v_avg_crit
FROM arena_participants WHERE room_id = p_room AND NOT is_bot;
SELECT count(*) INTO v_present FROM arena_participants WHERE room_id = p_room;

v_total := CASE v_room.mode
WHEN 'duel' THEN 2
WHEN 'team' THEN 6
ELSE LEAST(40, GREATEST(v_present + (v_present % 2), 2 * (5 + floor(random() * 16)::int)))
END;

IF NOT arena_bots_on() THEN
IF v_present < 2 THEN
UPDATE arena_rooms SET starts_at = now() + interval '10 seconds' WHERE id = p_room;
RETURN;
END IF;
v_total := v_present;
END IF;

FOR i IN 1..GREATEST(0, v_total - v_present) LOOP
v_lvl := GREATEST(1, round(v_avg_lvl)::int + floor(random() * 3)::int - 1);
v_name := v_names[1 + floor(random() * array_length(v_names, 1))::int]
|| CASE WHEN random() < 0.35 THEN '_' || (10 + floor(random() * 90)::int) ELSE '' END;
IF EXISTS (SELECT 1 FROM arena_participants WHERE room_id = p_room AND name = v_name) THEN
v_name := v_name || (100 + floor(random() * 900)::int);
END IF;
-- Approximately even real power, independent ±4% combat-stat variation.
-- Winners are always decided by arena_resolve_round, not preset outcomes.
v_hp := GREATEST(1, LEAST(200000000, round(v_avg_hp * (0.96 + random() * 0.08))::bigint))::int;
INSERT INTO arena_participants (room_id, is_bot, name, level, rating, attack, defense, crit_chance, max_hp, hp, joined_at)
VALUES (p_room, true, v_name, v_lvl,
GREATEST(100, round(v_avg_rating + (random() - 0.5) * 120)::int),
GREATEST(1, LEAST(200000000, round(v_avg_attack * (0.96 + random() * 0.08))::bigint))::int,
GREATEST(0, LEAST(200000000, round(v_avg_defense * (0.96 + random() * 0.08))::bigint))::int,
LEAST(75, GREATEST(0, round(v_avg_crit + (random() - 0.5) * 4)::int)),
v_hp, v_hp, now() + make_interval(secs => i * 0.001));
PERFORM arena_msg(p_room, 'join', NULL, v_name || ' входит на арену');
END LOOP;

WITH shuffled AS (
SELECT id, row_number() OVER (ORDER BY random()) AS rn FROM arena_participants WHERE room_id = p_room
)
UPDATE arena_participants p SET team = CASE WHEN s.rn % 2 = 1 THEN 1 ELSE 2 END, hp = p.max_hp
FROM shuffled s WHERE p.id = s.id;

UPDATE arena_rooms SET status = 'active', round_no = 1, round_started_at = now(),
round_deadline = now() + make_interval(secs => timeout_seconds)
WHERE id = p_room;
PERFORM arena_schedule_bots(p_room);

SELECT count(*) FILTER (WHERE team = 1), count(*) FILTER (WHERE team = 2) INTO v_c1, v_c2
FROM arena_participants WHERE room_id = p_room;
PERFORM arena_msg(p_room, 'system', NULL,
CASE WHEN v_room.mode = 'duel' THEN 'Бой начался! Выбери зону удара и две зоны защиты.'
ELSE 'Бой начался! Волки (' || v_c1 || ') против Воронов (' || v_c2 || '). Выбери цель, зону удара и две зоны защиты.' END);
END;
$expected_start$
 OR resolve_body IS DISTINCT FROM $expected_resolve$
DECLARE
v_room arena_rooms%ROWTYPE;
v_alive uuid[];
m arena_moves%ROWTYPE;
a arena_participants%ROWTYPE;
t arena_participants%ROWTYPE;
v_blocks text[];
v_blocked boolean;
v_crit boolean;
v_mult numeric;
v_dmg int;
v_new_hp int;
v_zone text;
v_alive1 int;
v_alive2 int;
v_hp1 bigint;
v_hp2 bigint;
BEGIN
SELECT * INTO v_room FROM arena_rooms WHERE id = p_room;
PERFORM arena_bot_moves(p_room, true);

FOR a IN
SELECT * FROM arena_participants p
WHERE p.room_id = p_room AND p.hp > 0
AND NOT EXISTS (SELECT 1 FROM arena_moves mv WHERE mv.room_id = p_room AND mv.round_no = v_room.round_no AND mv.participant_id = p.id)
LOOP
UPDATE arena_participants SET hp = 0 WHERE id = a.id;
PERFORM arena_msg(p_room, 'timeout', NULL,
a.name || ' не сделал ход за ' || v_room.timeout_seconds || ' сек. и выбывает по тайму');
END LOOP;

v_alive := ARRAY(SELECT id FROM arena_participants WHERE room_id = p_room AND hp > 0);

FOR m IN
SELECT * FROM arena_moves
WHERE room_id = p_room AND round_no = v_room.round_no AND participant_id = ANY(v_alive)
ORDER BY random()
LOOP
SELECT * INTO a FROM arena_participants WHERE id = m.participant_id;
SELECT * INTO t FROM arena_participants
WHERE id = m.target_id AND room_id = p_room AND team <> a.team AND id = ANY(v_alive);
IF NOT FOUND THEN
SELECT * INTO t FROM arena_participants
WHERE room_id = p_room AND team <> a.team AND id = ANY(v_alive) ORDER BY random() LIMIT 1;
IF NOT FOUND THEN CONTINUE; END IF;
END IF;

v_zone := arena_zone_ru(m.attack_zone);

IF random() * 100 < 6 THEN
PERFORM arena_msg(p_room, 'dodge', a.name, a.name || ' → ' || t.name || ': уклоняется от удара ' || v_zone);
CONTINUE;
END IF;

SELECT block_zones INTO v_blocks FROM arena_moves
WHERE room_id = p_room AND round_no = v_room.round_no AND participant_id = t.id;
v_blocked := m.attack_zone = ANY(COALESCE(v_blocks, '{}'::text[]));
v_crit := random() * 100 < a.crit_chance;
v_mult := CASE m.attack_zone WHEN 'head' THEN 1.25 WHEN 'legs' THEN 0.85 ELSE 1.0 END;
v_dmg := GREATEST(1, round((a.attack * (0.85 + random() * 0.3) - t.defense * 0.5) * v_mult))::int;

IF v_blocked AND NOT v_crit THEN
PERFORM arena_msg(p_room, 'block', a.name, a.name || ' → ' || t.name || ': удар ' || v_zone || ' заблокирован');
CONTINUE;
END IF;
IF v_blocked THEN
v_dmg := GREATEST(1, round(v_dmg * 0.8))::int;
ELSIF v_crit THEN
v_dmg := round(v_dmg * 1.6)::int;
END IF;

UPDATE arena_participants SET hp = GREATEST(0, hp - v_dmg) WHERE id = t.id RETURNING hp INTO v_new_hp;
UPDATE arena_participants SET damage_dealt = damage_dealt + LEAST(v_dmg, t.hp) WHERE id = a.id;
PERFORM arena_msg(p_room, CASE WHEN v_crit THEN 'crit' ELSE 'hit' END, a.name,
a.name || ' → ' || t.name || ': ' ||
CASE WHEN v_blocked THEN 'пробивает блок, удар ' WHEN v_crit THEN 'критический удар ' ELSE 'удар ' END ||
v_zone || ', −' || v_dmg || ' [' || v_new_hp || '/' || t.max_hp || ']');

IF v_new_hp = 0 AND t.hp > 0 THEN
UPDATE arena_participants SET kills = kills + 1 WHERE id = a.id;
PERFORM arena_msg(p_room, 'kill', a.name, t.name || ' падает от удара ' || a.name);
END IF;
END LOOP;

SELECT count(*) FILTER (WHERE team = 1 AND hp > 0), count(*) FILTER (WHERE team = 2 AND hp > 0),
COALESCE(sum(hp) FILTER (WHERE team = 1), 0), COALESCE(sum(hp) FILTER (WHERE team = 2), 0)
INTO v_alive1, v_alive2, v_hp1, v_hp2
FROM arena_participants WHERE room_id = p_room;

IF v_alive1 = 0 AND v_alive2 = 0 THEN
PERFORM arena_finish(p_room, NULL);
ELSIF v_alive1 = 0 THEN
PERFORM arena_finish(p_room, 2);
ELSIF v_alive2 = 0 THEN
PERFORM arena_finish(p_room, 1);
ELSIF v_room.round_no >= 60 THEN
PERFORM arena_finish(p_room, CASE WHEN v_hp1 > v_hp2 THEN 1 WHEN v_hp2 > v_hp1 THEN 2 ELSE NULL END);
ELSE
UPDATE arena_rooms SET round_no = round_no + 1, round_started_at = now(),
round_deadline = now() + make_interval(secs => timeout_seconds)
WHERE id = p_room;
PERFORM arena_schedule_bots(p_room);
END IF;
END;
$expected_resolve$
 THEN RAISE EXCEPTION 'rune_arena_function_drift'; END IF;
END $guard$;
CREATE TABLE IF NOT EXISTS territory_private.rune_arena_fighters_v1 (
 room_id uuid NOT NULL REFERENCES public.arena_rooms(id),
 participant_id uuid NOT NULL REFERENCES public.arena_participants(id),
 player_id uuid REFERENCES public.players(id),
 is_bot boolean NOT NULL,
 snapshot jsonb NOT NULL,
 totals jsonb NOT NULL CHECK (jsonb_typeof(totals)='object'),
 PRIMARY KEY(room_id,participant_id),
 CHECK ((is_bot AND player_id IS NULL) OR (NOT is_bot AND player_id IS NOT NULL))
);
ALTER TABLE territory_private.rune_arena_fighters_v1 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON territory_private.rune_arena_fighters_v1 FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION territory_private.runes_pin_arena_room_v1(p_room uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $pin$
DECLARE fighter record; snap jsonb; effects jsonb; existing territory_private.rune_arena_fighters_v1%ROWTYPE;
BEGIN
 IF p_room IS NULL OR NOT EXISTS(SELECT 1 FROM public.arena_rooms WHERE id=p_room AND status='waiting')
 THEN RAISE EXCEPTION 'rune_arena_invalid_start'; END IF;
 FOR fighter IN SELECT id,user_id,is_bot FROM public.arena_participants WHERE room_id=p_room ORDER BY user_id NULLS LAST,id LOOP
  SELECT * INTO existing FROM territory_private.rune_arena_fighters_v1 WHERE room_id=p_room AND participant_id=fighter.id;
  IF FOUND THEN
   IF existing.is_bot IS DISTINCT FROM fighter.is_bot OR existing.player_id IS DISTINCT FROM fighter.user_id
   THEN RAISE EXCEPTION 'rune_arena_participant_changed'; END IF;
   CONTINUE;
  END IF;
  IF fighter.is_bot AND fighter.user_id IS NULL THEN
   -- Explicit server-defined bot build: no ownership is fabricated.
   SELECT jsonb_build_object('schema','territory-rune-bot-snapshot/1','slots',
     jsonb_agg(jsonb_build_object('slotId',slot_id,'runeId',NULL,'level',0) ORDER BY slot_id))
    INTO snap FROM (SELECT DISTINCT slot_id FROM territory_private.rune_catalog_v1) slots;
   effects:='{}'::jsonb;
  ELSIF NOT fighter.is_bot AND fighter.user_id IS NOT NULL THEN
   snap:=public.territory_runes_pin_battle_v1(fighter.user_id,p_room,'arena');
   effects:=public.territory_runes_battle_effects_v1(fighter.user_id,p_room,'arena')->'totals';
  ELSE RAISE EXCEPTION 'rune_arena_invalid_participant'; END IF;
  INSERT INTO territory_private.rune_arena_fighters_v1(room_id,participant_id,player_id,is_bot,snapshot,totals)
   VALUES(p_room,fighter.id,fighter.user_id,fighter.is_bot,snap,effects);
 END LOOP;
END $pin$;
CREATE OR REPLACE FUNCTION territory_private.runes_arena_damage_v1(
 p_room uuid,p_attacker uuid,p_defender uuid,p_base integer,p_guarded boolean
) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $damage$
DECLARE a jsonb; d jsonb; attack_bp integer; guard_bp integer; versus_guard integer;
BEGIN
 IF p_room IS NULL OR p_attacker IS NULL OR p_defender IS NULL OR p_guarded IS NULL
 THEN RAISE EXCEPTION 'rune_arena_invalid_damage'; END IF;
 -- A room started before the migration has no rune snapshots at all.
 -- Preserve the exact old damage formula for that already-running room.
 IF NOT EXISTS(SELECT 1 FROM territory_private.rune_arena_fighters_v1 WHERE room_id=p_room)
 THEN RETURN p_base; END IF;
 SELECT totals INTO a FROM territory_private.rune_arena_fighters_v1 WHERE room_id=p_room AND participant_id=p_attacker;
 IF NOT FOUND THEN RAISE EXCEPTION 'rune_arena_snapshot_missing'; END IF;
 SELECT totals INTO d FROM territory_private.rune_arena_fighters_v1 WHERE room_id=p_room AND participant_id=p_defender;
 IF NOT FOUND THEN RAISE EXCEPTION 'rune_arena_snapshot_missing'; END IF;
 attack_bp:=least(2500,coalesce((a->>'damage_bonus_bp')::integer,0)+coalesce((a->>'rune_combat_damage_bp')::integer,0));
 versus_guard:=CASE WHEN p_guarded THEN coalesce((a->>'damage_vs_guard_bp')::integer,0) ELSE 0 END;
 guard_bp:=least(2500,(CASE WHEN p_guarded THEN coalesce((d->>'guard_absorb_bp')::integer,0) ELSE 0 END)+coalesce((d->>'rune_combat_guard_bp')::integer,0));
 RETURN territory_private.runes_apply_damage_v1(attack_bp,versus_guard,guard_bp,p_base);
END $damage$;
CREATE OR REPLACE FUNCTION territory_private.runes_arena_chance_v1(
 p_room uuid,p_attacker uuid,p_defender uuid,p_kind text,p_base numeric
) RETURNS numeric LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $chance$
DECLARE a jsonb; d jsonb; delta_bp integer;
BEGIN
 IF p_room IS NULL OR p_attacker IS NULL OR p_defender IS NULL
   OR p_kind IS NULL OR p_kind NOT IN ('dodge','crit') OR p_base IS NULL
 THEN RAISE EXCEPTION 'rune_arena_invalid_chance'; END IF;
 -- A room started before the migration has no rune snapshots at all.
 -- Preserve the exact old damage formula for that already-running room.
 IF NOT EXISTS(SELECT 1 FROM territory_private.rune_arena_fighters_v1 WHERE room_id=p_room)
 THEN RETURN p_base; END IF;
 SELECT totals INTO a FROM territory_private.rune_arena_fighters_v1 WHERE room_id=p_room AND participant_id=p_attacker;
 IF NOT FOUND THEN RAISE EXCEPTION 'rune_arena_snapshot_missing'; END IF;
 SELECT totals INTO d FROM territory_private.rune_arena_fighters_v1 WHERE room_id=p_room AND participant_id=p_defender;
 IF NOT FOUND THEN RAISE EXCEPTION 'rune_arena_snapshot_missing'; END IF;
 IF p_kind='dodge' THEN
   delta_bp:=coalesce((d->>'dodge_chance_bp')::integer,0)+coalesce((d->>'rune_combat_dodge_bp')::integer,0)-coalesce((a->>'accuracy_bp')::integer,0)-coalesce((a->>'rune_combat_accuracy_bp')::integer,0);
 ELSE delta_bp:=coalesce((a->>'crit_chance_bp')::integer,0)+coalesce((a->>'rune_combat_crit_bp')::integer,0); END IF;
 delta_bp:=greatest(-2500,least(2500,delta_bp));
 RETURN greatest(0,least(100,p_base+delta_bp::numeric/100));
END $chance$;
REVOKE ALL ON FUNCTION territory_private.runes_pin_arena_room_v1(uuid),
 territory_private.runes_arena_damage_v1(uuid,uuid,uuid,integer,boolean),
 territory_private.runes_arena_chance_v1(uuid,uuid,uuid,text,numeric)
 FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.arena_start_room(p_room uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
v_room arena_rooms%ROWTYPE;
v_humans int;
v_present int;
v_total int;
v_avg_lvl numeric;
v_avg_rating numeric;
v_avg_attack numeric;
v_avg_defense numeric;
v_avg_hp numeric;
v_avg_crit numeric;
v_lvl int;
v_hp int;
v_name text;
v_names text[] := ARRAY['Рагнар','Сигурд','Хельга','Бьорн','Ивар','Астрид','Торвальд','Фрейя','Улаф','Лагерта',
'Хротгар','Эйрик','Сольвейг','Гуннар','Кнуд','Ингрид','Харальд','Тюр','Вали','Сван','ВолкСевера','Берсерк',
'ТёмныйЯрл','Ледоруб','Медведь','Skald','Valkyr','Drakkar','Fenrir','NordKing','Wolfhart','Grimnir','Тордис',
'Хаук','Агнар','Ярослав','Мстислав','Дружинник','СтальнойКулак','Варяг'];
v_c1 int;
v_c2 int;
i int;
BEGIN
SELECT * INTO v_room FROM arena_rooms WHERE id = p_room;
-- Scale newly generated combat opponents to real participating heroes.
SELECT count(*), COALESCE(avg(level), 1), COALESCE(avg(rating), 1000),
       COALESCE(avg(attack), 20), COALESCE(avg(defense), 5),
       COALESCE(avg(max_hp), 100), COALESCE(avg(crit_chance), 5)
INTO v_humans, v_avg_lvl, v_avg_rating,
     v_avg_attack, v_avg_defense, v_avg_hp, v_avg_crit
FROM arena_participants WHERE room_id = p_room AND NOT is_bot;
SELECT count(*) INTO v_present FROM arena_participants WHERE room_id = p_room;

v_total := CASE v_room.mode
WHEN 'duel' THEN 2
WHEN 'team' THEN 6
ELSE LEAST(40, GREATEST(v_present + (v_present % 2), 2 * (5 + floor(random() * 16)::int)))
END;

IF NOT arena_bots_on() THEN
IF v_present < 2 THEN
UPDATE arena_rooms SET starts_at = now() + interval '10 seconds' WHERE id = p_room;
RETURN;
END IF;
v_total := v_present;
END IF;

FOR i IN 1..GREATEST(0, v_total - v_present) LOOP
v_lvl := GREATEST(1, round(v_avg_lvl)::int + floor(random() * 3)::int - 1);
v_name := v_names[1 + floor(random() * array_length(v_names, 1))::int]
|| CASE WHEN random() < 0.35 THEN '_' || (10 + floor(random() * 90)::int) ELSE '' END;
IF EXISTS (SELECT 1 FROM arena_participants WHERE room_id = p_room AND name = v_name) THEN
v_name := v_name || (100 + floor(random() * 900)::int);
END IF;
-- Approximately even real power, independent ±4% combat-stat variation.
-- Winners are always decided by arena_resolve_round, not preset outcomes.
v_hp := GREATEST(1, LEAST(200000000, round(v_avg_hp * (0.96 + random() * 0.08))::bigint))::int;
INSERT INTO arena_participants (room_id, is_bot, name, level, rating, attack, defense, crit_chance, max_hp, hp, joined_at)
VALUES (p_room, true, v_name, v_lvl,
GREATEST(100, round(v_avg_rating + (random() - 0.5) * 120)::int),
GREATEST(1, LEAST(200000000, round(v_avg_attack * (0.96 + random() * 0.08))::bigint))::int,
GREATEST(0, LEAST(200000000, round(v_avg_defense * (0.96 + random() * 0.08))::bigint))::int,
LEAST(75, GREATEST(0, round(v_avg_crit + (random() - 0.5) * 4)::int)),
v_hp, v_hp, now() + make_interval(secs => i * 0.001));
PERFORM arena_msg(p_room, 'join', NULL, v_name || ' входит на арену');
END LOOP;

WITH shuffled AS (
SELECT id, row_number() OVER (ORDER BY random()) AS rn FROM arena_participants WHERE room_id = p_room
)
UPDATE arena_participants p SET team = CASE WHEN s.rn % 2 = 1 THEN 1 ELSE 2 END, hp = p.max_hp
FROM shuffled s WHERE p.id = s.id;

-- Snapshot only after all participants, including bots, have been created.
PERFORM territory_private.runes_pin_arena_room_v1(p_room);
UPDATE arena_rooms SET status = 'active', round_no = 1, round_started_at = now(),
round_deadline = now() + make_interval(secs => timeout_seconds)
WHERE id = p_room;
PERFORM arena_schedule_bots(p_room);

SELECT count(*) FILTER (WHERE team = 1), count(*) FILTER (WHERE team = 2) INTO v_c1, v_c2
FROM arena_participants WHERE room_id = p_room;
PERFORM arena_msg(p_room, 'system', NULL,
CASE WHEN v_room.mode = 'duel' THEN 'Бой начался! Выбери зону удара и две зоны защиты.'
ELSE 'Бой начался! Волки (' || v_c1 || ') против Воронов (' || v_c2 || '). Выбери цель, зону удара и две зоны защиты.' END);
END;
$function$;

CREATE OR REPLACE FUNCTION public.arena_resolve_round(p_room uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
v_room arena_rooms%ROWTYPE;
v_alive uuid[];
m arena_moves%ROWTYPE;
a arena_participants%ROWTYPE;
t arena_participants%ROWTYPE;
v_blocks text[];
v_blocked boolean;
v_crit boolean;
v_mult numeric;
v_dmg int;
v_new_hp int;
v_zone text;
v_alive1 int;
v_alive2 int;
v_hp1 bigint;
v_hp2 bigint;
BEGIN
SELECT * INTO v_room FROM arena_rooms WHERE id = p_room;
PERFORM arena_bot_moves(p_room, true);

FOR a IN
SELECT * FROM arena_participants p
WHERE p.room_id = p_room AND p.hp > 0
AND NOT EXISTS (SELECT 1 FROM arena_moves mv WHERE mv.room_id = p_room AND mv.round_no = v_room.round_no AND mv.participant_id = p.id)
LOOP
UPDATE arena_participants SET hp = 0 WHERE id = a.id;
PERFORM arena_msg(p_room, 'timeout', NULL,
a.name || ' не сделал ход за ' || v_room.timeout_seconds || ' сек. и выбывает по тайму');
END LOOP;

v_alive := ARRAY(SELECT id FROM arena_participants WHERE room_id = p_room AND hp > 0);

FOR m IN
SELECT * FROM arena_moves
WHERE room_id = p_room AND round_no = v_room.round_no AND participant_id = ANY(v_alive)
ORDER BY random()
LOOP
SELECT * INTO a FROM arena_participants WHERE id = m.participant_id;
SELECT * INTO t FROM arena_participants
WHERE id = m.target_id AND room_id = p_room AND team <> a.team AND id = ANY(v_alive);
IF NOT FOUND THEN
SELECT * INTO t FROM arena_participants
WHERE room_id = p_room AND team <> a.team AND id = ANY(v_alive) ORDER BY random() LIMIT 1;
IF NOT FOUND THEN CONTINUE; END IF;
END IF;

v_zone := arena_zone_ru(m.attack_zone);

IF random() * 100 < territory_private.runes_arena_chance_v1(p_room,a.id,t.id,'dodge',6) THEN
PERFORM arena_msg(p_room, 'dodge', a.name, a.name || ' → ' || t.name || ': уклоняется от удара ' || v_zone);
CONTINUE;
END IF;

SELECT block_zones INTO v_blocks FROM arena_moves
WHERE room_id = p_room AND round_no = v_room.round_no AND participant_id = t.id;
v_blocked := m.attack_zone = ANY(COALESCE(v_blocks, '{}'::text[]));
v_crit := random() * 100 < territory_private.runes_arena_chance_v1(p_room,a.id,t.id,'crit',a.crit_chance);
v_mult := CASE m.attack_zone WHEN 'head' THEN 1.25 WHEN 'legs' THEN 0.85 ELSE 1.0 END;
v_dmg := GREATEST(1, round((a.attack * (0.85 + random() * 0.3) - t.defense * 0.5) * v_mult))::int;

IF v_blocked AND NOT v_crit THEN
PERFORM arena_msg(p_room, 'block', a.name, a.name || ' → ' || t.name || ': удар ' || v_zone || ' заблокирован');
CONTINUE;
END IF;
IF v_blocked THEN
v_dmg := GREATEST(1, round(v_dmg * 0.8))::int;
ELSIF v_crit THEN
v_dmg := round(v_dmg * 1.6)::int;
END IF;

-- The original targeting, dodge, block, crit and base damage have already resolved.
v_dmg := territory_private.runes_arena_damage_v1(p_room,a.id,t.id,v_dmg,v_blocked);
UPDATE arena_participants SET hp = GREATEST(0, hp - v_dmg) WHERE id = t.id RETURNING hp INTO v_new_hp;
UPDATE arena_participants SET damage_dealt = damage_dealt + LEAST(v_dmg, t.hp) WHERE id = a.id;
PERFORM arena_msg(p_room, CASE WHEN v_crit THEN 'crit' ELSE 'hit' END, a.name,
a.name || ' → ' || t.name || ': ' ||
CASE WHEN v_blocked THEN 'пробивает блок, удар ' WHEN v_crit THEN 'критический удар ' ELSE 'удар ' END ||
v_zone || ', −' || v_dmg || ' [' || v_new_hp || '/' || t.max_hp || ']');

IF v_new_hp = 0 AND t.hp > 0 THEN
UPDATE arena_participants SET kills = kills + 1 WHERE id = a.id;
PERFORM arena_msg(p_room, 'kill', a.name, t.name || ' падает от удара ' || a.name);
END IF;
END LOOP;

SELECT count(*) FILTER (WHERE team = 1 AND hp > 0), count(*) FILTER (WHERE team = 2 AND hp > 0),
COALESCE(sum(hp) FILTER (WHERE team = 1), 0), COALESCE(sum(hp) FILTER (WHERE team = 2), 0)
INTO v_alive1, v_alive2, v_hp1, v_hp2
FROM arena_participants WHERE room_id = p_room;

IF v_alive1 = 0 AND v_alive2 = 0 THEN
PERFORM arena_finish(p_room, NULL);
ELSIF v_alive1 = 0 THEN
PERFORM arena_finish(p_room, 2);
ELSIF v_alive2 = 0 THEN
PERFORM arena_finish(p_room, 1);
ELSIF v_room.round_no >= 60 THEN
PERFORM arena_finish(p_room, CASE WHEN v_hp1 > v_hp2 THEN 1 WHEN v_hp2 > v_hp1 THEN 2 ELSE NULL END);
ELSE
UPDATE arena_rooms SET round_no = round_no + 1, round_started_at = now(),
round_deadline = now() + make_interval(secs => timeout_seconds)
WHERE id = p_room;
PERFORM arena_schedule_bots(p_room);
END IF;
END;
$function$;
COMMIT;
